import {Repository} from './repository.js';
import * as D from './domain.js';
import {renderChart,exportRetro} from './visuals.js';
const repo=new Repository(),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=D.money,btn=(l,a,x='',k='')=>'<button class="btn '+k+'" data-action="'+a+'" '+x+'>'+l+'</button>';
let route=location.hash.slice(1)||'inicio',selectedSession=null,hallTab='finance',filters={},chartType='cumulative',chartPlayers=[],chartFrom='',chartTo='',retroPeriod='all',retroFrom='',retroTo='',statusText='',dialogReturn=null;
const navs=[['inicio','⌂','Início'],['mesa','♣','Mesa ao Vivo'],['placar','♛','Placar da Noite'],['arquivo','▤','Arquivo das Pokerzadas'],['hall','♜','Hall da Fama'],['stats','↗','Estatísticas'],['retro','✧','Retrospectiva Lendária'],['jogadores','♧','Jogadores'],['config','⚙','Configurações']];
const state=()=>repo.state,player=id=>state().players.find(p=>p.id===id)||{id,name:'Jogador'},current=()=>state()?.sessions.find(s=>s.id===selectedSession)||state()?.sessions.find(s=>s.status==='active')||state()?.sessions.at(-1);
const initials=n=>n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function avatar(p,size=''){return '<span class="avatar '+size+'">'+(p.avatar&&/^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(p.avatar)?'<img src="'+esc(p.avatar)+'" alt="">':esc(initials(p.name)))+'</span>';}
const empty=(i,h,p,a='')=>'<div class="empty"><div class="symbol">'+i+'</div><h3>'+h+'</h3><p>'+p+'</p>'+a+'</div>';
const metric=(l,v,n,i='♣')=>'<div class="stat"><div class="stat-label">'+l+'<span>'+i+'</span></div><div class="stat-value">'+v+'</div><small>'+n+'</small></div>';
const fmtDate=d=>new Date(d).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',year:'numeric'});
const fmtStamp=d=>new Date(d).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'});
const statusLabel=s=>({active:'Em andamento',finished:'Finalizada',cancelled:'Cancelada'}[s.status]);
const badge=s=>'<span class="badge '+s.status+'">'+statusLabel(s)+'</span>';
const netHtml=n=>'<span class="'+(n>0?'positive':n<0?'negative':'muted')+'">'+(n>0?'+':'')+money(n)+'</span>';
const pageHead=(tag,name,desc,actions='')=>'<div class="page-title"><div><span class="eyebrow">'+tag+'</span><h1>'+name+'</h1><p>'+desc+'</p></div><div class="actions">'+actions+'</div></div>';
const brand='<div class="brand"><div class="brand-icon">♣</div><div><b>POKERZADA<br>LENDÁRIA</b><small>O clube da nossa turma</small></div></div>';
function tableArt(){return '<div class="hero-art" aria-hidden="true"><div class="hero-felt"></div><div class="playing-card">A ♠<span class="big-suit">♠</span></div><div class="playing-card red">K ♥<span class="big-suit">♥</span></div><div class="chip-stack"><span class="chip" style="--chip:#ae3745">1</span><span class="chip" style="--chip:#c1a15e">25</span><span class="chip" style="--chip:#24764b">5</span></div></div>';}
const features=()=>'<div class="feature-strip">'+[['retro','✧','Sua retrospectiva lendária','Os grandes momentos, em um cartão para a turma.'],['stats','↗','A história em números','Compare resultados e acompanhe a evolução.'],['config','◉','As fichas do seu jeito','Cinco valores. As cores da sua mesa.']].map(([r,i,t,d])=>'<a href="#'+r+'" class="feature"><span class="symbol">'+i+'</span><div><b>'+t+'</b><p>'+d+'</p></div></a>').join('')+'</div>';
function welcome(){return '<div class="welcome"><div class="welcome-header">'+brand+'<span class="badge">PÔQUER PRESENCIAL · MEMÓRIAS REAIS</span></div><section class="hero"><div><div class="eyebrow">♣ &nbsp; OS AMIGOS. A MESA. AS HISTÓRIAS.</div><h1>Grandes noites.<br><em>Histórias lendárias.</em></h1><p>A partida acontece entre amigos. Aqui, cada entrada, cada mão memorável e cada resultado encontram seu lugar.</p><div class="hero-actions">'+btn('Entrar no clube &nbsp; ↗','login','','primary')+btn('Explorar demonstração','demo','','ghost')+'</div><p class="help" style="margin:18px 0 0">A demonstração salva somente neste navegador.<br>As partidas reais usam o banco compartilhado.</p></div>'+tableArt()+'</section>'+features()+'<footer class="footer"><span>A Pokerzada Lendária ♣</span><span>O jogo é presencial. A resenha é eterna.</span></footer></div>';}
function render(){if(!state()){$('#app').innerHTML=welcome();return;}document.body.classList.toggle('reduce-motion',!!state().settings.reducedMotion);const pages={inicio:home,mesa:live,placar:score,arquivo:archive,hall:hall,stats:stats,retro:retro,jogadores:players,config:settings};$('#app').innerHTML='<div class="shell"><aside class="sidebar">'+brand+'<div class="nav-label">O CLUBE</div><nav class="nav" aria-label="Principal">'+navs.map((n,i)=>(i===7?'<div class="nav-label">A TROPA</div>':'')+'<a href="#'+n[0]+'" class="'+(route===n[0]?'active':'')+'"><span>'+n[1]+'</span><em style="font-style:normal">'+n[2]+'</em></a>').join('')+'</nav><div class="sidebar-bottom">♣ &nbsp; Feito para a nossa turma<br><br><b>A resenha é eterna.</b></div></aside><div><header class="topbar"><div class="breadcrumb">O clube <span>/ &nbsp; '+(navs.find(n=>n[0]===route)?.[2]||'Início')+'</span></div><div class="top-actions"><span class="status" id="sync-status">'+esc(statusText)+'</span>'+btn('Sair','logout','','small ghost')+avatar({name:repo.mode==='demo'?'Demo':repo.auth?.user?.email||'Organizador'})+'</div></header><main id="main">'+(repo.mode==='demo'?'<div class="notice"><span>DEMONSTRAÇÃO · Os registros ficam apenas neste navegador.</span><button data-action="login">Conectar banco ↗</button></div>':'')+(repo.pending?'<div class="notice"><span>Um envio está pendente de conferência.</span><button data-action="pending">Conferir tentativa</button></div>':'')+(pages[route]||home)()+'<footer class="footer"><span>♣ A Pokerzada Lendária</span><span>Entre amigos, cada noite tem sua história.</span></footer></main></div></div><nav class="mobile-nav" aria-label="Navegação do celular">'+[['inicio','⌂','Início'],['mesa','♣','Mesa'],['arquivo','▤','Arquivo'],['hall','♛','Hall'],['mais','☰','Mais']].map(n=>'<a href="#'+n[0]+'" '+(n[0]==='mais'?'data-action="more"':'')+' class="'+(route===n[0]?'active':'')+'"><span>'+n[1]+'</span>'+n[2]+'</a>').join('')+'</nav>';if(route==='stats')drawChart();}
function home(){const sum=D.summary(state()),active=state().sessions.find(s=>s.status==='active'),recent=[...state().sessions].sort((a,b)=>b.startedAt.localeCompare(a.startedAt)).slice(0,3);return '<section class="hero"><div><div class="eyebrow">♣ &nbsp; BEM-VINDO AO CLUBE</div><h1>A mesa é nossa.<br><em>A noite é lendária.</em></h1><p>Reúna a tropa, distribua as fichas e deixe as contas com a gente. A próxima história começa aqui.</p><div class="hero-actions">'+btn('＋ &nbsp; Iniciar Pokerzada','new','','primary')+(active?btn('Voltar à mesa &nbsp; →','open','data-id="'+active.id+'"','ghost'):btn('Conhecer a tropa','navigate','data-route="jogadores"','ghost'))+'</div></div>'+tableArt()+'</section><div class="stats-grid">'+metric('Pokerzadas realizadas',sum.games,'Noites finalizadas')+metric('Total na mesa',money(sum.total),'Entradas, re-buys e ajustes','◇')+metric('Integrantes da tropa',state().players.filter(p=>p.active).length,'Jogadores ativos','♧')+metric('Rodadas memoráveis',sum.rounds,'Somente rodadas registradas','♠')+'</div><div class="grid-2"><section class="panel"><div class="section-head"><div><h2>Últimas Pokerzadas</h2><p>Cada mesa tem uma história.</p></div><a class="text-link" href="#arquivo">Ver arquivo ↗</a></div>'+(recent.length?recent.map(sessionRow).join(''):empty('♣','A primeira história está por vir','Comece uma Pokerzada para registrar a primeira noite da turma.',btn('Preparar a mesa','new','','small')))+'</section><section class="panel"><div class="section-head"><div><h2>Os nomes da noite</h2><p>Quem está escrevendo a história.</p></div><a class="text-link" href="#hall">↗</a></div>'+(sum.stats.length?[...sum.stats].sort((a,b)=>b.net-a.net).slice(0,3).map((p,i)=>'<div class="crew"><span class="pos">0'+(i+1)+'</span>'+avatar(p)+'<div class="info"><b>'+esc(p.name)+'</b><small>'+p.games+' partidas finalizadas</small></div><span class="amount">'+netHtml(p.net)+'</span></div>').join(''):state().players.slice(0,3).map(p=>'<div class="crew">'+avatar(p)+'<div class="info"><b>'+esc(p.name)+'</b><small>Pronto para a primeira Pokerzada</small></div><span class="muted">♧</span></div>').join(''))+'</section></div>'+features();}
function sessionRow(s){const dt=new Date(s.startedAt);return '<div class="session-row"><div class="date-box">'+dt.toLocaleDateString('pt-BR',{day:'2-digit',timeZone:'America/Sao_Paulo'})+'<small>'+dt.toLocaleDateString('pt-BR',{month:'short',timeZone:'America/Sao_Paulo'}).replace('.','')+'</small></div><div class="info"><b>'+esc(s.name)+'</b><small>'+esc(s.ancient)+' · '+s.participants.length+' jogadores · '+money(D.totals(s).invested)+'</small></div>'+badge(s)+btn('↗','open','data-id="'+s.id+'" aria-label="Abrir '+esc(s.name)+'"','small ghost')+'</div>';}
function sessionPicker(){return state().sessions.length>1?'<label class="field" style="max-width:300px;margin-bottom:20px">Sessão<select id="session-select">'+state().sessions.map(s=>'<option value="'+s.id+'" '+(s.id===current()?.id?'selected':'')+'>'+esc(s.name)+' · '+statusLabel(s)+'</option>').join('')+'</select></label>':'';}
function noSession(){return empty('♣','A mesa está esperando','Crie uma sessão e escolha quem vai participar.',btn('Iniciar Pokerzada','new','','primary'));}

function live(){const s=current();if(!s)return noSession();if(s.status!=='active')return score();const t=D.totals(s);return pageHead('A NOITE ESTÁ ACONTECENDO',esc(s.name),'Ancião: '+esc(s.ancient)+' · '+fmtDate(s.startedAt),btn('Encerrar Pokerzada','navigate','data-route="placar"','primary'))+sessionPicker()+'<div class="live-layout"><div><div class="arena"><div class="table-felt"></div><div class="table-center"><div class="display">Pokerzada<br>Lendária ♣</div><small>CLUBE DA NOSSA TURMA</small><strong>'+money(t.invested)+'</strong><small>TOTAL INVESTIDO</small></div>'+s.participants.map((p,i)=>{const a=i/s.participants.length*2*Math.PI-Math.PI/2;return '<button class="seat" style="--x:'+(50+42*Math.cos(a))+'%;--y:'+(50+38*Math.sin(a))+'%;--mx:'+(50+38*Math.cos(a))+'%;--my:'+(50+42*Math.sin(a))+'%" data-action="seat" data-id="'+p.playerId+'" aria-label="Abrir painel de '+esc(player(p.playerId).name)+'">'+avatar(player(p.playerId))+'<span class="seat-name">'+esc(player(p.playerId).name)+'</span><small>'+money(D.invested(s,p.playerId))+' · '+D.rebuys(s,p.playerId).length+' RB'+(!p.present?' · Ausente':'')+'</small></button>';}).join('')+'</div><div class="seat-list panel" style="margin-top:15px">'+s.participants.map(p=>'<div class="crew">'+avatar(player(p.playerId))+'<div class="info"><b>'+esc(player(p.playerId).name)+'</b><small>'+money(D.invested(s,p.playerId))+' investidos</small></div>'+btn('Abrir','seat','data-id="'+p.playerId+'"','small')+'</div>').join('')+'</div></div><aside class="live-side"><div class="panel"><span class="eyebrow">O CAIXA DA NOITE</span><div class="total-value" style="margin-top:15px">'+money(t.invested)+'</div><div class="label-value"><span>Jogadores</span><b>'+s.participants.length+'</b></div><div class="label-value"><span>Re-buys</span><b>'+D.rebuys(s).length+'</b></div><div class="label-value"><span>Entrada / re-buy</span><b>'+money(s.buyin)+' / '+money(s.rebuy)+'</b></div>'+btn('Configurar fichas','sessionChips','','ghost small')+'</div><div class="panel"><span class="eyebrow">SEU JEITO DE REGISTRAR</span><h2 style="font-size:24px;margin:15px 0 8px">'+(s.mode==='quick'?'Pokerzada Express':'Pokerzada Lendária')+'</h2><p class="help">As rodadas são opcionais e não alteram o caixa.</p>'+btn(s.mode==='quick'?'Ativar modo completo':'Usar modo rápido','toggleMode','','ghost small')+(s.mode==='full'?btn('＋ Registrar rodada','round','','primary'):'')+'</div></aside></div><section class="panel" style="margin-top:20px"><div class="section-head"><div><h2>As mãos da noite</h2><p>Estatísticas independentes do caixa.</p></div>'+(s.mode==='full'?btn('＋ Rodada','round','','small'):'<span class="badge">Registros preservados</span>')+'</div>'+roundList(s)+'</section>';}
function roundList(s){const rounds=s.rounds.filter(r=>!r.deleted).sort((a,b)=>a.number-b.number);return rounds.length?'<div class="table-wrap"><table><thead><tr><th>Rodada</th><th>Vencedor(es)</th><th>Mão</th><th>Registro</th><th></th></tr></thead><tbody>'+rounds.map(r=>'<tr><td>#'+r.number+'</td><td>'+r.winners.map(id=>esc(player(id).name)).join(' + ')+(r.winners.length>1?' <span class="badge">Dividida</span>':'')+'</td><td>'+esc(r.hand||'Não informada')+'</td><td>'+r.cards.length+' cartas'+(r.note?' · '+esc(r.note):'')+'</td><td>'+btn(s.status==='active'?'Editar':'Ver','round','data-id="'+r.id+'"','small ghost')+(s.status==='active'?btn('Excluir','deleteRound','data-id="'+r.id+'"','small danger'):'')+'</td></tr>').join('')+'</tbody></table></div>':empty('♠','Nenhuma rodada registrada','O caixa continua funcionando normalmente. Registre as mãos quando quiser.');}
function resultTable(s){return '<div class="table-wrap"><table><thead><tr><th>Jogador</th><th>Entrada</th><th>Re-buys</th><th>Investido</th><th>Recebido</th><th>Resultado</th></tr></thead><tbody>'+D.results(s).map(r=>'<tr><td>'+avatar(player(r.playerId))+esc(player(r.playerId).name)+'</td><td>'+money(s.buyin)+'</td><td>'+money(D.rebuys(s,r.playerId).reduce((a,e)=>a+e.amount,0))+'</td><td>'+money(r.invested)+'</td><td>'+(r.final===null?'Pendente':money(r.final))+'</td><td>'+(r.net===null?'—':netHtml(r.net))+'</td></tr>').join('')+'</tbody></table></div>';}
function duration(s){const m=Math.max(0,Math.round((new Date(s.endedAt||Date.now())-new Date(s.startedAt))/60000));return Math.floor(m/60)+'h '+m%60+'min de sessão';}
function score(){const s=current();if(!s)return noSession();const t=D.totals(s),rs=D.results(s),max=Math.max(...rs.map(r=>r.net??0)),min=Math.min(...rs.map(r=>r.net??0)),losses=rs.filter(r=>r.net===min&&min<0),wins=rs.filter(r=>r.net===max&&max>0);return pageHead(s.status==='finished'?'UMA NOITE PARA O ARQUIVO':'CONFERÊNCIA DA MESA','Placar da Noite',esc(s.name)+' · Ancião: '+esc(s.ancient),s.status==='active'?btn('Voltar à mesa','navigate','data-route="mesa"','ghost'):btn('Relatório completo','report','data-id="'+s.id+'"','ghost'))+sessionPicker()+(s.status==='finished'?'<div class="champion"><div class="crown">♛</div><span class="eyebrow">REI'+(wins.length>1?'S':'')+' DA MESA</span><h2>'+esc(wins.length?wins.map(r=>player(r.playerId).name).join(' & '):'Uma mesa equilibrada')+'</h2><strong>'+(max>0?'+'+money(max):'Sem lucro individual')+'</strong><p class="help" style="margin-top:15px">Maior resultado líquido da noite</p><p class="help">'+(losses.length?'Maior prejuízo: '+esc(losses.map(r=>player(r.playerId).name).join(' & '))+' · '+money(min):'Nenhum prejuízo individual')+'</p></div>':'')+'<div class="stats-grid">'+metric('Total investido',money(t.invested),s.participants.length+' jogadores')+metric('Total recebido',money(t.received),t.missing+' apurações pendentes','◇')+metric('Re-buys',D.rebuys(s).length,'Registrados nesta sessão','◉')+metric('Rodadas',s.rounds.filter(r=>!r.deleted).length,duration(s),'♠')+'</div><section class="panel"><div class="section-head"><div><h2>'+(s.status==='active'?'Quanto cada um recebeu?':'O resultado de cada jogador')+'</h2><p>Informe R$ 0,00 para quem terminou sem fichas.</p></div>'+badge(s)+'</div>'+(s.status==='active'?s.participants.map(p=>{const id=p.playerId,v=s.finals[id],inv=D.invested(s,id);return '<div class="closing-row"><div class="name">'+avatar(player(id))+'<div>'+esc(player(id).name)+'<small style="display:block">'+money(inv)+' investidos</small></div></div><label class="field">Valor recebido (R$)<input inputmode="decimal" id="final-'+id+'" value="'+esc((finalDrafts[id]?.session.id===s.id?finalDrafts[id].value:undefined)??(v===undefined?'':D.inputMoney(v)))+'" placeholder="Não informado"></label><div style="display:flex;gap:5px">'+btn('Salvar','saveFinal','data-id="'+id+'"','small')+btn('Fichas','count','data-id="'+id+'"','small ghost')+'</div><div class="net">'+(v===undefined?'Pendente':netHtml(v-inv))+'</div></div>';}).join(''):resultTable(s))+'<div class="validation '+(t.difference||t.missing?'warn':'')+'">'+(t.missing?t.missing+' jogador(es) ainda precisam de apuração.':t.difference===0?'Mesa fechada! Tudo conferido. ♣️':t.difference>0?'Faltam distribuir '+money(t.difference)+'. Confira fichas e apurações.':'Foram informados '+money(-t.difference)+' a mais. Confira os lançamentos.')+'<div class="help">Investido '+money(t.invested)+' − recebido '+money(t.received)+' − ajustes de caixa '+money(t.adjustments)+' = '+money(t.difference)+'</div></div>'+(s.cashAdjustments.length?'<details><summary>Ajustes de caixa</summary>'+s.cashAdjustments.map(a=>'<p class="help">'+money(a.amount)+' · '+esc(a.reason)+'</p>').join('')+'</details>':'')+(s.status==='active'?'<div class="form-actions">'+btn('Ajuste de caixa','cash','','ghost')+btn('Finalizar e salvar','finish',t.missing||t.difference?'disabled':'','primary')+'</div>':s.status==='finished'?'<div class="form-actions">'+btn('Abrir correção auditada','reopen','','ghost')+'</div>':'<p class="help">Partida cancelada: '+esc(s.cancelReason)+'</p>')+'</section>';}
function archive(){const list=state().sessions.filter(s=>(!filters.player||s.participants.some(p=>p.playerId===filters.player))&&D.within(s,filters.from,filters.to)&&(!filters.ancient||s.ancient===filters.ancient)&&(!filters.mode||s.mode===filters.mode)&&(!filters.status||s.status===filters.status)&&(!filters.result||D.results(s).some(r=>(!filters.player||r.playerId===filters.player)&&r.net!==null&&(filters.result==='positive'?r.net>0:filters.result==='negative'?r.net<0:r.net===0)))).sort((a,b)=>b.startedAt.localeCompare(a.startedAt));const sel=(k,l,opts)=>'<label class="field">'+l+'<select data-filter="'+k+'"><option value="">Todos</option>'+opts.map(([v,t])=>'<option value="'+esc(v)+'" '+(filters[k]===v?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label>';return pageHead('AS HISTÓRIAS CONTINUAM','Arquivo das Pokerzadas','Consulte os resultados e os registros completos de cada noite.',btn('Exportar CSV','csv','','ghost'))+'<div class="filters">'+sel('player','Jogador',state().players.map(p=>[p.id,p.name]))+'<label class="field">De<input type="date" data-filter="from" value="'+(filters.from||'')+'"></label><label class="field">Até<input type="date" data-filter="to" value="'+(filters.to||'')+'"></label>'+sel('ancient','Ancião',[...new Set(state().sessions.map(s=>s.ancient))].map(a=>[a,a]))+sel('mode','Modo',[['quick','Express'],['full','Lendária']])+sel('status','Situação',[['active','Em andamento'],['finished','Finalizada'],['cancelled','Cancelada']])+sel('result','Resultado',[['positive','Lucro'],['negative','Prejuízo'],['neutral','Neutro']])+'</div><section class="panel">'+(list.length?list.map(sessionRow).join(''):empty('▤','Nenhuma sessão neste filtro','As noites registradas aparecerão aqui.'))+'</section>';}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function modal(name,content){dialogReturn=document.activeElement;$('#dialog').innerHTML='<div class="dialog-head"><div><span class="eyebrow">A POKERZADA LENDÁRIA ♣</span><h2 id="dialog-title">'+name+'</h2></div><button data-action="close" aria-label="Fechar">×</button></div>'+content;if(!$('#dialog').open)$('#dialog').showModal();}
function close(){$('#dialog').close();dialogReturn?.focus?.();}
async function commit(type,payload,s=current()){await repo.send(type,payload,s);render();}
function formError(form,e){form.querySelector('.error').textContent=e.message||String(e);}
const formData=form=>Object.fromEntries(new FormData(form));
const chipsFrom=(form,base)=>base.map((c,i)=>({...c,color:form.elements['chip'+i].value}));
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}


function monthlyParticipation(id){const m={};D.validSessions(state()).filter(s=>s.participants.some(p=>p.playerId===id)).forEach(s=>{const k=D.localDate(s.startedAt).slice(0,7);m[k]=(m[k]||0)+1;});return Object.entries(m).map(([k,v])=>k+': '+v).join(' · ');}
function hall(){const st=D.statistics(state()).filter(p=>p.games),cols={finance:['Lucro acumulado','Lucro médio','Melhor noite','Pior noite','Noites + / − / =','Sessões com lucro'],rebuys:['Re-buys','Média / partida','Máximo / noite','Valor em re-buys','Partidas'],participation:['Partidas','Primeira participação','Noites + / − / =','Frequência mensal'],rounds:['Vitórias individuais','Empates','Trincas','Full Houses','Mãos raras']},sorted=[...st].sort((a,b)=>hallTab==='finance'?b.net-a.net:hallTab==='rebuys'?b.rebuys-a.rebuys:hallTab==='participation'?b.games-a.games:b.wins-a.wins);return pageHead('OS NOMES QUE FICAM','Hall da Fama','Rankings calculados somente com sessões finalizadas e válidas.')+'<div class="tabs">'+[['finance','♛ Financeiro'],['rebuys','◉ Re-buys'],['participation','♧ Participação'],['rounds','♠ Rodadas']].map(([k,t])=>'<button data-action="hallTab" data-id="'+k+'" class="'+(hallTab===k?'active':'')+'">'+t+'</button>').join('')+'</div><section class="panel">'+(sorted.length?'<div class="table-wrap"><table><thead><tr><th>Jogador</th>'+cols[hallTab].map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+sorted.map(p=>{const cells=hallTab==='finance'?[netHtml(p.net),money(Math.round(p.net/p.games)),money(p.best),money(p.worst),p.positive+' / '+p.negative+' / '+p.neutral,Math.round(p.positive/p.games*100)+'%']:hallTab==='rebuys'?[p.rebuys,(p.rebuys/p.games).toFixed(2),p.maxRebuys,money(p.rebuyAmount),p.games]:hallTab==='participation'?[p.games,fmtDate(p.first),p.positive+' / '+p.negative+' / '+p.neutral,monthlyParticipation(p.id)]:[p.wins,p.ties,p.hands[6],p.hands[3],p.rare];return '<tr><td>'+avatar(p)+esc(p.name)+'</td>'+cells.map(v=>'<td class="num">'+v+'</td>').join('')+'</tr>';}).join('')+'</tbody></table></div>':empty('♛','O Hall está esperando suas lendas','Finalize uma sessão conferida para inaugurar os rankings.'))+'</section>'+(st.length?hallDetails(st):'')+(state().settings.achievements&&st.length?achievements(st):'');}
function hallDetails(st){let content='',heading='';if(hallTab==='rebuys'){heading='Menos re-buys, com contexto';content=[...st].sort((a,b)=>a.rebuys-b.rebuys||a.rebuys/a.games-b.rebuys/b.games).map(p=>'<div class="label-value"><b>'+esc(p.name)+'</b><span>'+p.rebuys+' re-buys · '+p.games+' partidas · '+(p.rebuys/p.games).toFixed(2)+'/partida</span></div>').join('');}if(hallTab==='participation'){heading='Menos participações';content=[...st].sort((a,b)=>a.games-b.games).map(p=>'<div class="label-value"><b>'+esc(p.name)+'</b><span>'+p.games+' partidas</span></div>').join('');}if(hallTab==='finance'){heading='Prejuízos acumulados';content=st.filter(p=>p.net<0).sort((a,b)=>a.net-b.net).map(p=>'<div class="label-value"><b>'+esc(p.name)+'</b>'+netHtml(p.net)+'</div>').join('')||'<p class="help">Nenhum prejuízo acumulado registrado.</p>';}if(hallTab==='rounds'){heading='Vitórias por categoria';content='<div class="table-wrap"><table><thead><tr><th>Jogador</th>'+D.HANDS.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+st.map(p=>'<tr><td>'+esc(p.name)+'</td>'+p.hands.map(n=>'<td>'+n+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="help">Vitórias individuais e empates são separados. Mãos raras incluem vitórias compartilhadas registradas.</p>';}return '<div class="panel" style="margin-top:20px"><h2>'+heading+'</h2>'+content+'</div>';}
function achievements(st){const maxNet=Math.max(...st.map(p=>p.net)),maxGames=Math.max(...st.map(p=>p.games)),badges=[['Lenda do Armário',st.filter(p=>p.net===maxNet&&p.net>0),'Maior lucro histórico positivo'],['Presença Confirmada',st.filter(p=>p.games===maxGames),'Maior número de partidas'],['O Sobrevivente',st.filter(p=>p.survivor),'Lucro em uma noite sem re-buys'],['Mão de Ouro',st.filter(p=>p.rare),'Quadra, Straight Flush ou Royal Flush registrado'],['O Veterano',st.filter(p=>p.games>=10),'10 ou mais sessões finalizadas'],['Rei da Mesa',st.filter(p=>D.validSessions(state()).some(s=>{const r=D.results(s);return r.some(x=>x.playerId===p.id&&x.net>0&&x.net===Math.max(...r.map(a=>a.net)));})),'Maior lucro positivo em uma noite']];return '<div class="section-head"><h2>Conquistas da tropa</h2></div><div class="retro-grid">'+badges.map(([n,ps,c])=>'<div class="retro-card"><span class="symbol">✧</span><h2>'+n+'</h2><strong>'+esc(ps.length?ps.map(p=>p.name).join(', '):'Ainda não conquistada')+'</strong><small>'+c+'</small></div>').join('')+'</div>';}
function stats(){return pageHead('CADA NOITE CONTA','Estatísticas da tropa','Explore resultados reais, sem estimar rodadas ausentes.')+'<div class="filters"><label class="field">Gráfico<select id="chart-type">'+[['cumulative','Resultado acumulado histórico'],['net','Lucro e prejuízo por partida'],['comparison','Comparação entre jogadores'],['monthly','Evolução mensal'],['rebuys','Re-buys por partida'],['participation','Participações por mês'],['hands','Categorias das mãos']].map(([v,t])=>'<option value="'+v+'" '+(v===chartType?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="field">De<input id="chart-from" type="date" value="'+chartFrom+'"></label><label class="field">Até<input id="chart-to" type="date" value="'+chartTo+'"></label></div><div class="check-grid" style="margin-bottom:20px">'+state().players.map(p=>'<label class="check"><input type="checkbox" data-chart-player="'+p.id+'" '+(!chartPlayers.length||chartPlayers.includes(p.id)?'checked':'')+'>'+esc(p.name)+'</label>').join('')+'</div><section class="panel"><div id="chart"></div><div class="chart-tooltip" id="chart-tooltip">Toque ou passe o mouse nos pontos para ver os valores.</div><div id="chart-data"></div></section>';}
function drawChart(){renderChart($('#chart'),$('#chart-data'),state(),{type:chartType,players:chartPlayers,from:chartFrom,to:chartTo},t=>{$('#chart-tooltip').textContent=t;});}
const retroSessions=()=>D.validSessions(state()).filter(s=>D.within(s,retroFrom,retroTo));
function retro(){const sum=D.summary(state(),retroSessions()),names=ps=>ps.length?ps.map(p=>p.name).join(' & '):'Ainda sem registro';return pageHead('REVIVA AS GRANDES NOITES','Retrospectiva Lendária','A história da turma, contada pelos registros.',btn('Criar cartão para compartilhar','exportRetro',sum.games?'':'disabled','primary'))+'<div class="filters"><label class="field">Período<select id="retro-period">'+[['all','Toda a história'],['month','Este mês'],['year','Este ano'],['custom','Personalizado']].map(([v,t])=>'<option value="'+v+'" '+(retroPeriod===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="field">De<input type="date" id="retro-from" value="'+retroFrom+'"></label><label class="field">Até<input type="date" id="retro-to" value="'+retroTo+'"></label></div>'+(sum.games?'<div class="stats-grid">'+metric('Pokerzadas',sum.games,'Finalizadas no período')+metric('Pessoas',sum.people,'Participantes únicos','♧')+metric('Rodadas épicas',sum.rounds,'Rodadas registradas','♠')+metric('Re-buys',sum.rebuys,'Sem incentivo de gasto','◉')+'</div><div class="retro-grid">'+[['♛','Rei da Mesa',names(sum.kings),sum.kings.length?money(sum.kings[0].net)+' de lucro acumulado':'Nenhum lucro positivo'],['♧','Presença Lendária',names(sum.presence),sum.presence.length?sum.presence[0].games+' participações':'Sem participações'],['↗','Maior Virada',names(sum.bestNight),sum.bestNight.length?money(sum.bestNight[0].best)+' · maior lucro em uma única noite':'Maior lucro individual em uma noite'],['♠','A mão do período',sum.commonHands.map(c=>c.hand).join(' & ')||'Não registrada',sum.commonHands.length?sum.commonHands[0].n+' registros por categoria':'Somente mãos informadas'],['◇','Maior prejuízo',names(sum.losses),sum.losses.length?money(sum.losses[0].net)+' acumulados':'Nenhum prejuízo'],['◉','Mais re-buys',names(sum.rebuyLeaders),sum.rebuyLeaders.length?sum.rebuyLeaders[0].rebuys+' registros':'Sem re-buys']].map(([i,t,n,c])=>'<div class="retro-card"><span class="symbol">'+i+'</span><h2>'+t+'</h2><strong>'+esc(n)+'</strong><small>'+esc(c)+'</small></div>').join('')+'</div><div class="panel" style="margin-top:20px"><h2>Recordes alcançados</h2>'+records(retroSessions())+'</div>':empty('✧','Toda lenda tem um começo','Finalize uma Pokerzada para gerar uma retrospectiva com dados reais.'));}
function records(sessions){let record=null,notes=[];for(const s of D.validSessions(state()).sort((a,b)=>a.startedAt.localeCompare(b.startedAt)||a.id.localeCompare(b.id))){const max=Math.max(...D.results(s).map(r=>r.net));if(max>0&&(record===null||max>record)){if(sessions.some(x=>x.id===s.id))notes.push('<p class="help">'+D.results(s).filter(r=>r.net===max).map(r=>esc(player(r.playerId).name)).join(' & ')+' · '+money(max)+' em '+esc(s.name)+' — '+(record===null?'primeiro recorde documentado':'novo maior lucro em uma noite')+'.</p>');record=max;}}return notes.join('')||'<p class="help">Nenhum novo recorde de lucro individual documentado neste período.</p>';}
function players(){return pageHead('QUEM FAZ A NOITE','A tropa lendária','Perfis permanentes. As histórias continuam mesmo depois de mudar o apelido.',btn('＋ Novo integrante','editPlayer','','primary'))+'<div class="player-grid">'+D.statistics(state()).map(p=>'<div class="panel player-card '+(!p.active?'inactive':'')+'">'+avatar(p,'xl')+'<h3>'+esc(p.name)+'</h3><span class="badge">'+(p.active?'Membro da tropa':'Desativado')+'</span><div class="mini-stats"><div><small>PARTIDAS</small>'+p.games+'</div><div><small>RESULTADO</small>'+netHtml(p.net)+'</div></div>'+btn('Ver perfil','profile','data-id="'+p.id+'"','ghost small')+'</div>').join('')+'</div>';}
function chipFields(chips){return '<div style="display:flex;flex-wrap:wrap;gap:20px">'+chips.map((c,i)=>'<label class="field" style="text-align:center"><span class="chip" style="--chip:'+c.color+';margin:10px">'+money(c.value)+'</span><span style="display:block">'+money(c.value)+'</span><input type="color" name="chip'+i+'" value="'+c.color+'" aria-label="Cor da ficha de '+money(c.value)+'" style="margin-top:10px"></label>').join('')+'</div>';}

function settings(){const c=state().settings;return pageHead('AS REGRAS DA CASA','Configurações','Personalize a mesa e mantenha os registros protegidos.')+'<form id="settings-form" class="panel settings-section"><h2>As fichas da turma</h2><p class="help">As cores padrão valem para novas sessões. Cada partida preserva sua configuração.</p>'+chipFields(c.chips)+'<div class="fields" style="margin-top:25px"><label class="field">Entrada padrão (R$)<input name="buyin" inputmode="decimal" value="'+D.inputMoney(c.buyin)+'" required></label><label class="field">Re-buy padrão (R$)<input name="rebuy" inputmode="decimal" value="'+D.inputMoney(c.rebuy)+'" required></label></div><div class="form-section"><label class="check"><input name="reducedMotion" type="checkbox" '+(c.reducedMotion?'checked':'')+'>Reduzir animações</label><label class="check" style="margin-top:8px"><input name="achievements" type="checkbox" '+(c.achievements?'checked':'')+'>Mostrar conquistas da turma</label></div><div class="error"></div><div class="form-actions"><button class="btn primary">Salvar preferências</button></div></form><div class="grid-even"><section class="panel"><h2>Dados e segurança</h2><p class="help">'+(repo.mode==='demo'?'Demonstração local. Conecte o Supabase para usar registros compartilhados.':'Os registros são validados pelo servidor. O apelido do Ancião não concede permissões.')+'</p><div style="display:flex;gap:9px;flex-wrap:wrap">'+btn('Exportar backup JSON','backup','','ghost')+btn('Exportar resultados CSV','csv','','ghost')+btn('Histórico de alterações','audit','','ghost')+'</div>'+(repo.mode==='demo'?'<div class="form-section"><label class="field">Restaurar backup na demonstração<input type="file" id="restore-file" accept=".json,application/json"></label>'+btn('Limpar demonstração','reset','','danger small')+'</div>':'')+'</section><section class="panel"><h2>Banco compartilhado</h2><p class="help">O acesso usa a conta de um organizador autorizado. Jogadores não precisam de conta.</p>'+btn('Configurar conexão / entrar','login','','ghost')+'<p class="help" style="margin-top:15px">Nunca insira uma chave administrativa. A implantação inclui o SQL e as instruções de autorização.</p></section></div>';}


let modalSession=null,roundDraft=null,photoDraft='',finalDrafts={};
const formEnd=(label='Salvar')=>'<div class="error" role="alert"></div><div class="form-actions">'+btn('Cancelar','close','','ghost')+'<button class="btn primary" type="submit">'+label+'</button></div>';
function showLogin(){modal('Entrar no clube','<form id="login-form"><p class="help">Entre com a conta de um organizador autorizado. Os jogadores não precisam criar contas.</p><div class="fields"><label class="field">E-mail do organizador<input name="email" type="email" autocomplete="username" required></label><label class="field">Senha<input name="password" type="password" autocomplete="current-password" required></label></div><details style="margin-top:20px"><summary>Configuração avançada da conexão</summary><div class="fields"><label class="field full">URL do projeto Supabase<input type="url" name="url" value="'+esc(repo.config.supabaseUrl||'')+'" required></label><label class="field full">Chave publicável<input name="key" value="'+esc(repo.config.publishableKey||'')+'" required autocomplete="off"></label></div><p class="help">Use somente chave publicável. Nunca insira secret ou service_role.</p></details><p class="help" style="margin-top:18px">Primeiro acesso: a conta deve ser criada e autorizada pelo responsável pelo projeto, conforme o guia de instalação. Um apelido de Ancião não libera acesso.</p>'+formEnd('Entrar e sincronizar')+'</form>');}
function newSession(){const c=state().settings;modal('Quem será o Ancião desta noite?','<form id="new-form"><div class="fields"><label class="field">Ancião responsável<input name="ancient" list="ancients" maxlength="60" required placeholder="Escolha ou digite um nome"><datalist id="ancients">'+state().players.map(p=>'<option value="'+esc(p.name)+'">').join('')+'</datalist></label><label class="field">Nome da Pokerzada (opcional)<input name="name" maxlength="100" placeholder="A noite das lendas"></label><label class="field">Data e horário<input type="datetime-local" name="startedAt" value="'+new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)+'" required></label><label class="field">Modo de registro<select name="mode"><option value="quick">Pokerzada Express</option><option value="full">Pokerzada Lendária</option></select></label><label class="field">Entrada inicial (R$)<input name="buyin" inputmode="decimal" value="'+D.inputMoney(c.buyin)+'" required></label><label class="field">Re-buy padrão (R$)<input name="rebuy" inputmode="decimal" value="'+D.inputMoney(c.rebuy)+'" required></label><label class="field full">Modalidade para registro de cartas<select name="variant"><option value="texas">Texas Hold’em · 2 cartas individuais</option><option value="omaha">Omaha · 4 cartas, usar 2 individuais e 3 comunitárias</option><option value="draw">Pôquer fechado · 5 cartas individuais</option></select></label></div><div class="form-section"><h3>Quem está na mesa? <small>Mínimo de 2 jogadores</small></h3><div class="check-grid">'+state().players.filter(p=>p.active).map(p=>'<label class="check"><input type="checkbox" name="players" value="'+p.id+'">'+avatar(p)+esc(p.name)+'</label>').join('')+'</div></div><details><summary>Cores das fichas desta sessão</summary>'+chipFields(c.chips)+'</details>'+formEnd('Abrir a mesa')+'</form>');}
function seat(id){const s=current(),p=player(id);modalSession=D.clone(s);modal(esc(p.name),'<div class="crew">'+avatar(p,'lg')+'<div class="info"><b>'+money(D.invested(s,id))+' investidos</b><small>'+D.rebuys(s,id).length+' re-buys · '+(s.participants.find(x=>x.playerId===id).present?'Presente':'Ausente')+'</small></div></div><form id="rebuy-form" data-player="'+id+'"><label class="field">Novo re-buy (R$)<input name="amount" inputmode="decimal" value="'+D.inputMoney(s.rebuy)+'" required></label><div class="error"></div><div class="form-actions" style="margin-top:10px"><button class="btn primary">＋ Adicionar re-buy</button></div></form><div style="display:flex;gap:8px;flex-wrap:wrap;margin:18px 0">'+btn('Contar fichas','count','data-id="'+id+'"')+btn('Valor final','finalModal','data-id="'+id+'"')+btn('Ver perfil','profile','data-id="'+id+'"')+btn('Ajustar investimento','adjust','data-id="'+id+'"')+btn('Marcar '+(s.participants.find(x=>x.playerId===id).present?'ausente':'presente'),'presence','data-id="'+id+'"')+'</div><h3>Entradas e re-buys</h3>'+s.entries.filter(e=>e.playerId===id).map(e=>'<div class="label-value"><div><b>'+({buyin:'Entrada inicial',rebuy:'Re-buy',adjustment:'Ajuste'}[e.kind])+'</b><small style="display:block">'+fmtStamp(e.at)+' · '+esc(e.actor)+(e.voided?' · ESTORNADO':'')+(e.reason?' · '+esc(e.reason):'')+'</small></div><div>'+money(e.amount)+' '+(!e.voided&&e.kind!=='buyin'?btn('Estornar','void','data-id="'+e.id+'"','small danger'):'')+'</div></div>').join('')+'<details><summary>Contagens anteriores</summary>'+s.counts.filter(c=>c.playerId===id).map(c=>'<p class="help">'+money(c.amount)+' · '+new Date(c.at).toLocaleString('pt-BR')+'</p>').join('')+'</details>');}
function count(id){const s=current();modalSession=D.clone(s);const last=s.counts.filter(c=>c.playerId===id).at(-1);modal('Fichas de '+esc(player(id).name),'<form id="count-form" data-player="'+id+'"><p class="help">Contar fichas não registra uma compra. Use a apuração no fechamento somente quando desejar.</p>'+s.chips.map((c,i)=>'<div class="counter-row"><span class="chip" style="--chip:'+c.color+'">'+money(c.value)+'</span><span class="value">'+money(c.value)+'</span>'+btn('−','counter','data-index="'+i+'" data-delta="-1" aria-label="Remover ficha de '+money(c.value)+'"','small')+'<input name="q'+i+'" type="number" min="0" max="1000000" step="1" value="'+(last?.quantities[i]||0)+'" aria-label="Quantidade de fichas de '+money(c.value)+'">'+btn('＋','counter','data-index="'+i+'" data-delta="1" aria-label="Adicionar ficha de '+money(c.value)+'"','small')+'</div>').join('')+'<div class="counter-total"><span>Total em fichas</span><strong id="count-total"></strong></div><label class="check" style="margin-top:20px"><input type="checkbox" name="useFinal" '+(route==='placar'?'checked':'')+'>Usar este total como valor final recebido</label>'+formEnd('Salvar contagem')+'</form>');updateCount();}
function updateCount(){try{$('#count-total').textContent=money(current().chips.reduce((a,c,i)=>a+D.integer(Number($('#count-form').elements['q'+i].value),0,1000000)*c.value,0));}catch{$('#count-total').textContent='Quantidade inválida';}}
function amountModal(type,id){modalSession=D.clone(current());const labels={adjust:'Ajustar investimento',cash:'Ajuste de caixa da mesa',final:'Registrar valor final'};modal(labels[type],'<form id="amount-form" data-type="'+type+'" data-player="'+(id||'')+'"><p class="help">'+(type==='cash'?'Saída de caixa: valor positivo. Entrada externa: valor negativo. Não use este ajuste para esconder uma divergência.':type==='adjust'?'Correção explícita do investimento. Use o sinal negativo para reduzir. O motivo fica no histórico.':'Informe quanto o jogador recebeu ao final, inclusive zero.')+'</p><label class="field">Valor em reais<input name="amount" inputmode="decimal" value="'+(type==='final'&&current().finals[id]!==undefined?D.inputMoney(current().finals[id]):'')+'" required></label>'+(type==='final'?'':'<label class="field" style="margin-top:15px">Motivo<input name="reason" required maxlength="500"></label>')+formEnd()+'</form>');}
function reasonModal(type,id){modalSession=D.clone(current());const labels={void:'Estornar lançamento',deleteRound:'Excluir rodada',reopen:'Abrir correção auditada',cancel:'Cancelar Pokerzada'};modal(labels[type],'<form id="reason-form" data-type="'+type+'" data-id="'+(id||'')+'"><p class="help">'+(type==='reopen'?'A sessão será reaberta e sairá temporariamente dos rankings até ser conferida e finalizada novamente. O fechamento anterior será preservado.':'A operação ficará registrada na auditoria e não apagará a origem dos dados.')+'</p><label class="field">Motivo obrigatório<textarea name="reason" maxlength="500" required></textarea></label>'+formEnd('Confirmar')+'</form>');}
function roundModal(id){const s=current();modalSession=D.clone(s);roundDraft=D.clone(s.rounds.find(r=>r.id===id)||{id:D.uuid(),number:Math.max(0,...s.rounds.filter(r=>!r.deleted).map(r=>r.number))+1,winners:[],hand:'',note:'',cards:[]});const r=roundDraft;modal(s.status==='active'?'Registrar rodada':'Rodada #'+r.number,'<form id="round-form"><fieldset '+(s.status!=='active'?'disabled':'')+' style="border:0;padding:0;margin:0"><div class="fields"><label class="field">Número da rodada<input name="number" type="number" min="1" max="100000" value="'+r.number+'" required></label><label class="field">Categoria (opcional)<select name="hand"><option value="">Não informar</option>'+D.HANDS.map(h=>'<option '+(r.hand===h?'selected':'')+'>'+h+'</option>').join('')+'</select></label></div><div class="form-section"><h3>Vencedor(es) <small>Selecione vários para divisão do pote</small></h3><div class="check-grid">'+s.participants.map(p=>'<label class="check"><input type="checkbox" name="winners" value="'+p.playerId+'" '+(r.winners.includes(p.playerId)?'checked':'')+'>'+esc(player(p.playerId).name)+'</label>').join('')+'</div></div><label class="field">Observação opcional<textarea name="note" maxlength="1000">'+esc(r.note)+'</textarea></label><details '+(r.cards.length?'open':'')+'><summary>Registrar cartas (opcional)</summary><label class="field">Adicionar cartas em<select id="card-owner">'+(s.variant!=='draw'?'<option value="board">Mesa · comunitárias</option>':'')+s.participants.map(p=>'<option value="'+p.playerId+'">'+esc(player(p.playerId).name)+'</option>').join('')+'</select></label><div id="card-picker"></div><div id="selected-cards" class="selected-cards"></div><p id="card-check" class="help"></p></details><div class="error"></div>'+(s.status==='active'?'<div class="form-actions"><button class="btn primary">Salvar rodada</button></div>':'')+'</fieldset></form>');paintCards();}
function paintCards(){const owner=$('#card-owner')?.value;if(!owner)return;$('#card-picker').innerHTML=D.SUITS.map(suit=>'<div class="card-picker">'+D.RANKS.map(rank=>{const c=roundDraft.cards.find(c=>c.rank===rank&&c.suit===suit);return '<button type="button" data-action="card" data-rank="'+rank+'" data-suit="'+suit+'" '+(c&&c.owner!==owner?'disabled':'')+' class="card-option '+(['♥','♦'].includes(suit)?'red ':'')+(c?'selected':'')+'">'+rank+'<span>'+suit+'</span></button>';}).join('')+'</div>').join('');$('#selected-cards').innerHTML=roundDraft.cards.map(c=>'<span class="mini-card '+(['♥','♦'].includes(c.suit)?'red':'')+'" title="'+esc(c.owner==='board'?'Mesa':player(c.owner).name)+'">'+c.rank+c.suit+' <small style="color:inherit">'+esc(c.owner==='board'?'Mesa':player(c.owner).name)+'</small></span>').join('');checkCards();}

function checkCards(){if(!roundDraft||!$('#card-check'))return;const winners=[...new FormData($('#round-form')).getAll('winners')],hand=$('#round-form').elements.hand.value;$('#card-check').textContent=winners.map(id=>{const result=D.evaluateRecorded(roundDraft.cards,id,current().variant);return player(id).name+': '+(result?(hand&&result!==hand?'atenção, cartas indicam '+result:result+' compatível com as cartas disponíveis'):'cartas insuficientes para verificar');}).join(' · ')||'Escolha um vencedor. Nenhuma carta será inventada.';}
function profile(id){const p=D.statistics(state()).find(p=>p.id===id),sessions=state().sessions.filter(s=>s.participants.some(x=>x.playerId===id));modal(esc(p.name),'<div style="text-align:center">'+avatar(p,'xl')+'<p class="help">Primeira participação válida: '+(p.first?fmtDate(p.first):'Ainda sem partidas finalizadas')+'</p></div><div class="stats-grid" style="grid-template-columns:1fr 1fr">'+metric('Partidas',p.games,p.positive+' positivas · '+p.negative+' negativas · '+p.neutral+' neutras')+metric('Resultado',netHtml(p.net),'Acumulado válido')+metric('Entradas',money(p.buyins),'Entradas iniciais')+metric('Re-buys',money(p.rebuyAmount),p.rebuys+' compras adicionais')+'</div><div class="label-value"><span>Melhor / pior noite</span><b>'+(p.best===null?'—':money(p.best)+' / '+money(p.worst))+'</b></div><div class="label-value"><span>Rodadas vencidas / empates</span><b>'+p.wins+' / '+p.ties+'</b></div>'+btn('Editar perfil','editPlayer','data-id="'+id+'"','ghost')+'<h3 style="margin-top:25px">Histórico de participações</h3>'+(sessions.map(sessionRow).join('')||'<p class="help">Nenhuma participação.</p>'));}
function editPlayer(id){const p=id?player(id):{name:'',avatar:'',active:true};photoDraft=p.avatar||'';modal(id?'Editar integrante':'Novo integrante','<form id="player-form" data-id="'+(id||'')+'"><label class="field">Nome ou apelido<input name="name" maxlength="60" value="'+esc(p.name)+'" required></label><div class="form-section"><label class="field">Foto personalizada<input type="file" id="photo-file" accept="image/png,image/jpeg,image/webp"></label><p class="help" id="photo-status">'+(p.avatar?'Foto atual preservada.':'Sem foto: usaremos as iniciais.')+'</p>'+btn('Usar iniciais','removePhoto','','small ghost')+'</div><label class="check"><input type="checkbox" name="active" '+(p.active?'checked':'')+'>Jogador ativo para novas sessões</label>'+formEnd('Salvar integrante')+'</form>');}
function audit(sessionId){const list=state().audit.filter(a=>!sessionId||a.sessionId===sessionId).slice().reverse();return list.length?list.map(a=>'<div class="audit"><b>'+esc(a.type)+'</b> · '+esc(a.actor)+'<small style="display:block">'+new Date(a.at).toLocaleString('pt-BR')+(a.reason?' · '+esc(a.reason):'')+'</small><details><summary>Ver alteração</summary><pre>'+esc(JSON.stringify({antes:a.before,depois:a.after},null,2))+'</pre></details></div>').join(''):'<p class="help">Nenhuma alteração registrada.</p>';}
function report(id){const s=state().sessions.find(x=>x.id===id);selectedSession=id;modal(esc(s.name),'<p class="help">'+fmtDate(s.startedAt)+' · Ancião: '+esc(s.ancient)+' · '+duration(s)+'</p>'+badge(s)+resultTable(s)+'<h3 style="margin-top:25px">Rodadas registradas</h3>'+roundList(s)+'<details><summary>Entradas e re-buys</summary>'+s.entries.map(e=>'<p class="help">'+esc(player(e.playerId).name)+' · '+esc(e.kind)+' · '+money(e.amount)+(e.voided?' · estornado':'')+'</p>').join('')+'</details><details><summary>Auditoria completa</summary>'+audit(id)+'</details><details><summary>Fechamentos anteriores ('+s.closures.length+')</summary><pre>'+esc(JSON.stringify(s.closures,null,2))+'</pre></details>'+btn('Abrir placar','navigate','data-route="placar"','primary')+(s.status==='active'?btn('Cancelar sessão','cancel','','danger'):''));
}
function confirmModal(title,description,action){modal(title,'<p>'+description+'</p><div class="form-actions">'+btn('Voltar','close','','ghost')+btn('Confirmar','confirmed','data-confirm="'+action+'"','primary')+'</div>');}
async function photo(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Escolha PNG, JPEG ou WebP.');if(file.size>10000000)throw Error('Escolha uma foto menor que 10 MB.');const bitmap=await createImageBitmap(file),c=document.createElement('canvas');c.width=c.height=240;const ctx=c.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,240,240);bitmap.close();return c.toDataURL('image/jpeg',.8);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{
 if(a==='close')close();else if(a==='demo'){repo.startDemo();route='inicio';location.hash=route;render();}
 else if(a==='login')showLogin();else if(a==='logout'){await repo.logout();render();}
 else if(a==='navigate'){close();route=b.dataset.route;location.hash=route;render();}
 else if(a==='new')newSession();else if(a==='open'){close();selectedSession=id;location.hash=state().sessions.find(s=>s.id===id).status==='active'?'mesa':'placar';route=location.hash.slice(1);render();}
 else if(a==='more')modal('Explore o clube','<nav class="nav">'+navs.map(n=>'<a href="#'+n[0]+'" data-action="navigate" data-route="'+n[0]+'"><span>'+n[1]+'</span>'+n[2]+'</a>').join('')+'</nav>');
 else if(a==='seat')seat(id);else if(a==='count')count(id);
 else if(a==='counter'){const el=$('#count-form').elements['q'+b.dataset.index];el.value=Math.max(0,Number(el.value)+Number(b.dataset.delta));updateCount();}
 else if(a==='finalModal')amountModal('final',id);else if(a==='adjust'||a==='cash')amountModal(a,id);
 else if(['void','deleteRound','reopen','cancel'].includes(a))reasonModal(a,id);
 else if(a==='round')roundModal(id);else if(a==='card'){const owner=$('#card-owner').value,idx=roundDraft.cards.findIndex(c=>c.rank===b.dataset.rank&&c.suit===b.dataset.suit);if(idx>=0)roundDraft.cards.splice(idx,1);else roundDraft.cards.push({rank:b.dataset.rank,suit:b.dataset.suit,owner});paintCards();}
 else if(a==='toggleMode'){b.disabled=true;await commit('mode',{mode:current().mode==='quick'?'full':'quick'});toast('Modo alterado. Todos os registros foram preservados.');}
 else if(a==='presence'){const p=current().participants.find(x=>x.playerId===id);b.disabled=true;await commit('presence',{playerId:id,present:!p.present});seat(id);}
 else if(a==='sessionChips'){modalSession=D.clone(current());modal('Fichas desta sessão','<form id="chips-form">'+chipFields(current().chips)+formEnd()+'</form>');}
 else if(a==='saveFinal'){const value=D.cents($('#final-'+id).value),s=finalDrafts[id]?.session||current();b.disabled=true;await commit('final',{playerId:id,amount:value},s);delete finalDrafts[id];for(const d of Object.values(finalDrafts))d.session=D.clone(current());render();toast('Apuração salva.');}
 else if(a==='finish'){modalSession=D.clone(current());confirmModal('Finalizar Pokerzada?','Os valores estão conferidos. A sessão será bloqueada para alterações comuns e entrará nos rankings.','finish');}
 else if(a==='confirmed'){b.disabled=true;if(b.dataset.confirm==='finish'){await commit('finalize',{},modalSession);close();toast('Pokerzada finalizada. Mesa conferida! ♣');}if(b.dataset.confirm==='reset'){repo.resetDemo();selectedSession=null;close();render();toast('Demonstração limpa.');}}
 else if(a==='profile')profile(id);else if(a==='editPlayer')editPlayer(id);else if(a==='removePhoto'){photoDraft='';$('#photo-status').textContent='As iniciais serão usadas.';}
 else if(a==='report')report(id);else if(a==='audit')modal('Histórico de alterações',audit());
 else if(a==='hallTab'){hallTab=id;render();}
 else if(a==='backup')download(JSON.stringify({...state(),exportedAt:new Date().toISOString(),environment:repo.mode},null,2),'pokerzada-backup-'+D.localDate(new Date())+'.json');
 else if(a==='csv'){const safe=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replaceAll('"','""')+'"';const rows=[['Partida','Data','Ancião','Jogador','Investido (centavos)','Recebido (centavos)','Resultado (centavos)','Re-buys'],...D.validSessions(state()).flatMap(s=>D.results(s).map(r=>[s.name,s.startedAt,s.ancient,player(r.playerId).name,r.invested,r.final,r.net,r.rebuys]))];download('\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'pokerzada-resultados.csv','text/csv;charset=utf-8');}
 else if(a==='reset')confirmModal('Limpar demonstração?','Somente os registros de teste deste navegador serão removidos. Exporte um backup se quiser preservá-los.','reset');
 else if(a==='pending')modal('Envio pendente','<p class="help">Uma tentativa pode ter chegado ao servidor sem resposta. Reenviar a mesma operação é seguro: seu identificador impede duplicação. Se houver conflito, atualize os dados antes de refazer.</p><div class="form-actions">'+btn('Conferir e descartar tentativa','discardPending','','ghost')+btn('Reenviar mesma operação','retry','','primary')+'</div>');
 else if(a==='retry'){b.disabled=true;await repo.retry();close();render();toast('Envio conferido.');}
 else if(a==='discardPending'){b.disabled=true;await repo.discardPending();close();render();toast('Dados atualizados. Confira antes de lançar novamente.');}
 else if(a==='exportRetro'){modal('Compartilhar a retrospectiva','<form id="export-form"><div class="fields"><label class="field">Formato<select name="format"><option value="vertical">Vertical · 1080 × 1350</option><option value="square">Quadrado · 1080 × 1080</option></select></label></div><div class="form-section"><label class="check"><input type="checkbox" name="money" checked>Mostrar valores financeiros</label><label class="check"><input type="checkbox" name="photos">Mostrar fotos dos destaques</label></div><div class="form-section"><h3>Destaques do cartão</h3><p class="help">Escolha de 1 a 4 resultados.</p>'+['Rei da Mesa','Presença Lendária','Maior Virada','A mão do período','Maior prejuízo','Mais re-buys'].map((label,i)=>'<label class="check"><input type="checkbox" name="highlights" value="'+i+'" '+(i<4?'checked':'')+'>'+label+'</label>').join('')+'</div>'+formEnd('Gerar prévia')+'</form>');}
 }catch(err){toast(err.message);b.disabled=false;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();if(f.dataset.busy)return;f.dataset.busy='1';const submit=f.querySelector('button[type=submit],button:not([type]):not([data-action])');if(submit)submit.disabled=true;try{const p=formData(f);
 if(f.id==='login-form'){await repo.connect({supabaseUrl:p.url,publishableKey:p.key});await repo.login(p.email,p.password);close();route='inicio';location.hash=route;render();toast('Bem-vindo ao clube.');}
 else if(f.id==='new-form'){const id=D.uuid();await commit('create',{id,name:p.name,ancient:p.ancient,mode:p.mode,variant:p.variant,buyin:D.cents(p.buyin),rebuy:D.cents(p.rebuy),startedAt:new Date(p.startedAt).toISOString(),players:new FormData(f).getAll('players'),chips:chipsFrom(f,state().settings.chips)},null);selectedSession=id;close();route='mesa';location.hash=route;render();}
 else if(f.id==='rebuy-form'){await commit('rebuy',{playerId:f.dataset.player,amount:D.cents(p.amount)},modalSession);seat(f.dataset.player);$('#dialog').classList.remove('pulse');void $('#dialog').offsetWidth;$('#dialog').classList.add('pulse');toast('Re-buy registrado.');}

 else if(f.id==='count-form'){await commit('count',{playerId:f.dataset.player,quantities:current().chips.map((_,i)=>D.integer(Number(p['q'+i]),0,1000000)),useFinal:!!p.useFinal},modalSession);close();toast('Contagem salva.');}
 else if(f.id==='amount-form'){const signed=String(p.amount).trim().startsWith('-'),amount=D.cents(String(p.amount).trim().replace(/^[-+]/,''))*(signed?-1:1);if(f.dataset.type==='final'&&amount<0)throw Error('O valor final não pode ser negativo.');await commit(f.dataset.type,{amount,playerId:f.dataset.player,reason:p.reason},modalSession);close();toast('Registro salvo.');}
 else if(f.id==='reason-form'){await commit(f.dataset.type,{reason:p.reason,entryId:f.dataset.id,roundId:f.dataset.id},modalSession);close();toast('Alteração registrada na auditoria.');}
 else if(f.id==='round-form'){await commit('round',{...roundDraft,number:Number(p.number),winners:new FormData(f).getAll('winners'),hand:p.hand,note:p.note},modalSession);close();toast('Rodada registrada. O caixa não foi alterado.');}
 else if(f.id==='player-form'){await commit('player',{id:f.dataset.id||D.uuid(),name:p.name,avatar:photoDraft,active:!!p.active},null);close();toast('Perfil salvo.');}
 else if(f.id==='settings-form'){await commit('settings',{buyin:D.cents(p.buyin),rebuy:D.cents(p.rebuy),chips:chipsFrom(f,state().settings.chips),reducedMotion:!!p.reducedMotion,achievements:!!p.achievements},null);toast('Preferências salvas.');}
 else if(f.id==='chips-form'){await commit('chips',{chips:chipsFrom(f,current().chips)},modalSession);close();toast('Cores da sessão atualizadas.');}
 else if(f.id==='export-form'){const selected=new FormData(f).getAll('highlights').map(Number);if(!selected.length||selected.length>4)throw Error('Escolha de 1 a 4 destaques.');const period=retroFrom||retroTo?(retroFrom||'Início')+' a '+(retroTo||'hoje'):'Toda a história';const image=await exportRetro(state(),retroSessions(),{format:p.format,money:!!p.money,photos:!!p.photos,period,selected});modal('Sua retrospectiva está pronta','<img class="export-preview" alt="Cartão da retrospectiva" src="'+image+'"><div class="form-actions"><a class="btn primary" href="'+image+'" download="retrospectiva-pokerzada.png">Baixar PNG</a>'+btn('Compartilhar','shareImage','','ghost')+'</div>');$('#dialog [data-action="shareImage"]').onclick=async()=>{try{const blob=await(await fetch(image)).blob(),file=new File([blob],'retrospectiva-pokerzada.png',{type:'image/png'});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'A Pokerzada Lendária'});else toast('Baixe a imagem e envie pelo seu aplicativo.');}catch(e){if(e.name!=='AbortError')toast(e.message);}};}
 }catch(err){formError(f,err);}finally{delete f.dataset.busy;if(submit)submit.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.closest('#count-form'))updateCount();if(e.target.id.startsWith('final-')){const id=e.target.id.slice(6);finalDrafts[id]={value:e.target.value,session:finalDrafts[id]?.session.id===current().id?finalDrafts[id].session:D.clone(current())};}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.filter){filters[el.dataset.filter]=el.value;render();}else if(el.id==='session-select'){selectedSession=el.value;finalDrafts={};render();}else if(el.id==='card-owner')paintCards();else if(el.closest('#round-form'))checkCards();else if(el.id==='photo-file'){photoDraft=await photo(el.files[0]);$('#photo-status').textContent='Foto preparada e reduzida para o perfil.';}else if(el.id==='restore-file'){if(repo.mode!=='demo')throw Error('Restauração disponível somente na demonstração.');if(el.files[0].size>20000000)throw Error('Backup muito grande.');repo.restoreDemo(JSON.parse(await el.files[0].text()));selectedSession=null;render();toast('Backup restaurado na demonstração.');}else if(el.id==='chart-type'){chartType=el.value;render();}else if(el.id==='chart-from'||el.id==='chart-to'){chartFrom=$('#chart-from').value;chartTo=$('#chart-to').value;render();}else if(el.dataset.chartPlayer){chartPlayers=$$('[data-chart-player]:checked').map(x=>x.dataset.chartPlayer);if(!chartPlayers.length)chartPlayers=['none'];drawChart();}else if(el.id==='retro-period'){retroPeriod=el.value;const today=D.localDate(new Date());if(retroPeriod==='month'){retroFrom=today.slice(0,7)+'-01';retroTo=today;}else if(retroPeriod==='year'){retroFrom=today.slice(0,4)+'-01-01';retroTo=today;}else if(retroPeriod==='all'){retroFrom='';retroTo='';}render();}else if(el.id==='retro-from'||el.id==='retro-to'){retroFrom=$('#retro-from').value;retroTo=$('#retro-to').value;retroPeriod='custom';render();}}catch(err){toast(err.message);}});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'inicio';if(route!=='mais'){render();window.scrollTo(0,0);}});
window.addEventListener('storage',e=>{if(repo.mode==='demo'&&e.key==='pokerzada-demo-v1'){repo.startDemo();render();}});
window.addEventListener('online',()=>{if(repo.mode==='cloud')repo.load().catch(()=>{});});
repo.changed=()=>{render();if(route==='placar')for(const [id,d]of Object.entries(finalDrafts)){const el=$('#final-'+id);if(el)el.value=d.value;}};
repo.status=t=>{statusText=t;const el=$('#sync-status');if(el)el.textContent=t;};
render();repo.resume().then(ok=>{if(ok)render();});



